def merge_intervals(intervals):
    if not intervals:
        return []

    # Create a copy of the intervals to avoid mutating the input
    intervals_copy = [interval.copy() for interval in intervals]
    # Sort intervals based on the start value
    intervals_copy.sort(key=lambda x: x[0])

    merged = []
    for interval in intervals_copy:
        if not merged:
            merged.append(interval)
        else:
            last = merged[-1]
            if interval[0] <= last[1]:
                # Overlapping or touching intervals, merge them
                new_start = last[0]
                new_end = max(last[1], interval[1])
                merged[-1] = [new_start, new_end]
            else:
                merged.append(interval)

    return merged

from collections import defaultdict, deque

def toposort(nodes, edges):
    in_degree = {node: 0 for node in nodes}
    graph = defaultdict(list)

    for src, dst in edges:
        if src == dst:
            raise ValueError("Self loop detected")
        graph[src].append(dst)
        in_degree[dst] += 1

    queue = deque(sorted([node for node in nodes if in_degree[node] == 0]))
    result = []

    while queue:
        current = queue.popleft()
        result.append(current)

        for neighbor in sorted(graph[current]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_weight + weight <= limit:
            current_batch.append(name)
            current_weight += weight
        else:
            if current_batch:
                batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    env_dict = {}
    lines = text.splitlines()
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    quote_pattern = re.compile(r'^[\'"](.*)[\'"]$')

    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue

        if '=' not in stripped_line:
            raise ValueError(f"Invalid line: {line}")

        key, value = stripped_line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key}")

        if quote_pattern.match(value):
            value = quote_pattern.match(value).group(1)

        env_dict[key] = value

    return env_dict

def parse_sse(chunks):
    buffer = b''
    events = []
    current_data = None

    for chunk in chunks:
        buffer += chunk

    # Decode the buffer to string, handling UTF-8 and replacing errors
    try:
        text = buffer.decode('utf-8', errors='replace')
    except Exception:
        return []

    lines = text.split('\n')
    for line in lines:
        if line.startswith('data: '):
            if current_data is None:
                current_data = line[6:].lstrip()
            else:
                current_data += '\n' + line[6:].lstrip()
        elif line == '':
            if current_data is not None:
                if current_data == '[DONE]':
                    return events
                events.append(current_data)
                current_data = None
        elif line.startswith('data:'):
            if current_data is None:
                current_data = line[5:].lstrip()
            else:
                current_data += '\n' + line[5:].lstrip()

    return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be nonnegative")
    if attempt == 0:
        return min(cap, base)
    # Use logarithms to avoid constructing huge integers
    import math
    if base == 0:
        return min(cap, 0.0)
    log_term = math.log2(base) + attempt
    if log_term > 1024:  # Prevent overflow in exponentiation
        return cap
    return min(cap, base * (2 ** attempt))

def fifo_admit(active, queued, budget, slots):
    if not all(q <= budget for q in queued):
        raise ValueError("A queued reservation exceeds the whole budget")

    active_sum = sum(active)
    active_len = len(active)

    admitted = []
    remaining = []

    for req in queued:
        if active_len < slots and active_sum + req <= budget:
            admitted.append(req)
            active_sum += req
            active_len += 1
        else:
            remaining.append(req)

    return admitted, remaining
